45	    public static final Setting<Boolean> ENABLED_SETTING = Setting.boolSetting("monitor.jvm.gc.enabled", true, Property.NodeScope);
46	    public static final Setting<TimeValue> REFRESH_INTERVAL_SETTING = Setting.timeSetting(
47	        "monitor.jvm.gc.refresh_interval",
48	        TimeValue.timeValueSeconds(1),
49	        TimeValue.timeValueSeconds(1),
50	        Property.NodeScope
51	    );
