53	    private static String GC_COLLECTOR_PREFIX = "monitor.jvm.gc.collector.";
54	    public static final Setting<Settings> GC_SETTING = Setting.groupSetting(GC_COLLECTOR_PREFIX, Property.NodeScope);
55	
56	    public static final Setting<Integer> GC_OVERHEAD_WARN_SETTING = Setting.intSetting(
57	        "monitor.jvm.gc.overhead.warn",
