78	    static class GcOverheadThreshold {
79	        final int warnThreshold;
80	        final int infoThreshold;
81	        final int debugThreshold;
82	
83	        GcOverheadThreshold(final int warnThreshold, final int infoThreshold, final int debugThreshold) {
84	            this.warnThreshold = warnThreshold;
85	            this.infoThreshold = infoThreshold;
86	            this.debugThreshold = debugThreshold;
87	        }
88	    }
