90	    static class GcThreshold {
91	        public final String name;
92	        public final long warnThreshold;
93	        public final long infoThreshold;
94	        public final long debugThreshold;
95	
96	        GcThreshold(String name, long warnThreshold, long infoThreshold, long debugThreshold) {
97	            this.name = name;
98	            this.warnThreshold = warnThreshold;
99	            this.infoThreshold = infoThreshold;
100	            this.debugThreshold = debugThreshold;
101	        }
102	
103	        @Override
104	        public String toString() {
105	            return "GcThreshold{"
106	                + "name='"
107	                + name
108	                + '\''
109	                + ", warnThreshold="
110	                + warnThreshold
111	                + ", infoThreshold="
112	                + infoThreshold
113	                + ", debugThreshold="
114	                + debugThreshold
115	                + '}';
116	        }
