119	    public JvmGcMonitorService(Settings settings, ThreadPool threadPool) {
120	        this.threadPool = threadPool;
121	
122	        this.enabled = ENABLED_SETTING.get(settings);
123	        this.interval = REFRESH_INTERVAL_SETTING.get(settings);
124	
125	        Map<String, GcThreshold> gcThresholds = new HashMap<>();
126	        Map<String, Settings> gcThresholdGroups = GC_SETTING.get(settings).getAsGroups();
127	        for (Map.Entry<String, Settings> entry : gcThresholdGroups.entrySet()) {
128	            String name = entry.getKey();
129	            TimeValue warn = getValidThreshold(entry.getValue(), entry.getKey(), "warn");
130	            TimeValue info = getValidThreshold(entry.getValue(), entry.getKey(), "info");
131	            TimeValue debug = getValidThreshold(entry.getValue(), entry.getKey(), "debug");
132	            gcThresholds.put(name, new GcThreshold(name, warn.millis(), info.millis(), debug.millis()));
133	        }
134	        gcThresholds.putIfAbsent(GcNames.YOUNG, new GcThreshold(GcNames.YOUNG, 1000, 700, 400));
135	        gcThresholds.putIfAbsent(GcNames.OLD, new GcThreshold(GcNames.OLD, 10000, 5000, 2000));
136	        gcThresholds.putIfAbsent("default", new GcThreshold("default", 10000, 5000, 2000));
137	        this.gcThresholds = unmodifiableMap(gcThresholds);
138	
139	        if (GC_OVERHEAD_WARN_SETTING.get(settings) <= GC_OVERHEAD_INFO_SETTING.get(settings)) {
140	            final String message = String.format(
141	                Locale.ROOT,
142	                "[%s] must be greater than [%s] [%d] but was [%d]",
143	                GC_OVERHEAD_WARN_SETTING.getKey(),
144	                GC_OVERHEAD_INFO_SETTING.getKey(),
145	                GC_OVERHEAD_INFO_SETTING.get(settings),
146	                GC_OVERHEAD_WARN_SETTING.get(settings)
147	            );
148	            throw new IllegalArgumentException(message);
149	        }
150	        if (GC_OVERHEAD_INFO_SETTING.get(settings) <= GC_OVERHEAD_DEBUG_SETTING.get(settings)) {
151	            final String message = String.format(
152	                Locale.ROOT,
153	                "[%s] must be greater than [%s] [%d] but was [%d]",
154	                GC_OVERHEAD_INFO_SETTING.getKey(),
155	                GC_OVERHEAD_DEBUG_SETTING.getKey(),
156	                GC_OVERHEAD_DEBUG_SETTING.get(settings),
157	                GC_OVERHEAD_INFO_SETTING.get(settings)
158	            );
159	            throw new IllegalArgumentException(message);
160	        }
161	
162	        this.gcOverheadThreshold = new GcOverheadThreshold(
163	            GC_OVERHEAD_WARN_SETTING.get(settings),
164	            GC_OVERHEAD_INFO_SETTING.get(settings),
165	            GC_OVERHEAD_DEBUG_SETTING.get(settings)
166	        );
167	
168	        logger.debug(
169	            "enabled [{}], interval [{}], gc_threshold [{}], overhead [{}, {}, {}]",
170	            this.enabled,
171	            this.interval,
172	            this.gcThresholds,
173	            this.gcOverheadThreshold.warnThreshold,
174	            this.gcOverheadThreshold.infoThreshold,
175	            this.gcOverheadThreshold.debugThreshold
176	        );
177	    }
