179	    private static TimeValue getValidThreshold(Settings settings, String key, String level) {
180	        final TimeValue threshold;
181	
182	        try {
183	            threshold = settings.getAsTime(level, null);
184	        } catch (RuntimeException ex) {
185	            final String settingValue = settings.get(level);
186	            throw new IllegalArgumentException(
187	                "failed to parse setting [" + getThresholdName(key, level) + "] with value [" + settingValue + "] as a time value",
188	                ex
189	            );
190	        }
191	
192	        if (threshold == null) {
193	            throw new IllegalArgumentException("missing gc_threshold for [" + getThresholdName(key, level) + "]");
194	        } else if (threshold.nanos() < 0) {
195	            final String settingValue = settings.get(level);
196	            throw new IllegalArgumentException(
197	                "invalid gc_threshold [" + getThresholdName(key, level) + "] value [" + settingValue + "]: value cannot be negative"
198	            );
199	        }
200	
201	        return threshold;
202	    }
203	
204	    private static String getThresholdName(String key, String level) {
205	        return GC_COLLECTOR_PREFIX + key + "." + level;
206	    }
