208	    @Override
209	    protected void doStart() {
210	        if (enabled == false) {
211	            return;
212	        }
213	        scheduledFuture = threadPool.scheduleWithFixedDelay(new JvmMonitor(gcThresholds, gcOverheadThreshold) {
214	            @Override
215	            void onMonitorFailure(Exception e) {
216	                logger.debug("failed to monitor", e);
217	            }
218	
219	            @Override
220	            void onSlowGc(final Threshold threshold, final long seq, final SlowGcEvent slowGcEvent) {
221	                logSlowGc(logger, threshold, seq, slowGcEvent, JvmGcMonitorService::buildPools);
222	            }
223	
224	            @Override
225	            void onGcOverhead(final Threshold threshold, final long current, final long elapsed, final long seq) {
226	                logGcOverhead(logger, threshold, current, elapsed, seq);
227	            }
228	        }, interval, EsExecutors.DIRECT_EXECUTOR_SERVICE);
229	    }
