231	    private static final String SLOW_GC_LOG_MESSAGE =
232	        "[gc][{}][{}][{}] duration [{}], collections [{}]/[{}], total [{}]/[{}], memory [{}]->[{}]/[{}], all_pools {}";
233	
234	    static void logSlowGc(
235	        final Logger logger,
236	        final JvmMonitor.Threshold threshold,
237	        final long seq,
238	        final JvmMonitor.SlowGcEvent slowGcEvent,
239	        BiFunction<JvmStats, JvmStats, String> pools
240	    ) {
241	
242	        final String name = slowGcEvent.currentGc.getName();
243	        final long elapsed = slowGcEvent.elapsed;
244	        final long totalGcCollectionCount = slowGcEvent.currentGc.getCollectionCount();
245	        final long currentGcCollectionCount = slowGcEvent.collectionCount;
246	        final TimeValue totalGcCollectionTime = slowGcEvent.currentGc.getCollectionTime();
247	        final TimeValue currentGcCollectionTime = slowGcEvent.collectionTime;
248	        final JvmStats lastJvmStats = slowGcEvent.lastJvmStats;
249	        final JvmStats currentJvmStats = slowGcEvent.currentJvmStats;
250	        final ByteSizeValue maxHeapUsed = slowGcEvent.maxHeapUsed;
251	
252	        switch (threshold) {
253	            case WARN:
254	                if (logger.isWarnEnabled()) {
255	                    logger.warn(
256	                        SLOW_GC_LOG_MESSAGE,
257	                        name,
258	                        seq,
259	                        totalGcCollectionCount,
260	                        currentGcCollectionTime,
261	                        currentGcCollectionCount,
262	                        TimeValue.timeValueMillis(elapsed),
263	                        currentGcCollectionTime,
264	                        totalGcCollectionTime,
265	                        lastJvmStats.getMem().getHeapUsed(),
266	                        currentJvmStats.getMem().getHeapUsed(),
267	                        maxHeapUsed,
268	                        pools.apply(lastJvmStats, currentJvmStats)
269	                    );
270	                }
271	                break;
272	            case INFO:
273	                if (logger.isInfoEnabled()) {
274	                    logger.info(
275	                        SLOW_GC_LOG_MESSAGE,
276	                        name,
277	                        seq,
278	                        totalGcCollectionCount,
279	                        currentGcCollectionTime,
280	                        currentGcCollectionCount,
281	                        TimeValue.timeValueMillis(elapsed),
282	                        currentGcCollectionTime,
283	                        totalGcCollectionTime,
284	                        lastJvmStats.getMem().getHeapUsed(),
285	                        currentJvmStats.getMem().getHeapUsed(),
286	                        maxHeapUsed,
287	                        pools.apply(lastJvmStats, currentJvmStats)
288	                    );
289	                }
290	                break;
291	            case DEBUG:
292	                if (logger.isDebugEnabled()) {
293	                    logger.debug(
294	                        SLOW_GC_LOG_MESSAGE,
295	                        name,
296	                        seq,
297	                        totalGcCollectionCount,
298	                        currentGcCollectionTime,
299	                        currentGcCollectionCount,
300	                        TimeValue.timeValueMillis(elapsed),
301	                        currentGcCollectionTime,
302	                        totalGcCollectionTime,
303	                        lastJvmStats.getMem().getHeapUsed(),
304	                        currentJvmStats.getMem().getHeapUsed(),
305	                        maxHeapUsed,
306	                        pools.apply(lastJvmStats, currentJvmStats)
307	                    );
308	                }
309	                break;
310	        }
311	    }
