313	    static String buildPools(JvmStats last, JvmStats current) {
314	        StringBuilder sb = new StringBuilder();
315	        for (JvmStats.MemoryPool currentPool : current.getMem()) {
316	            JvmStats.MemoryPool prevPool = null;
317	            for (JvmStats.MemoryPool pool : last.getMem()) {
318	                if (pool.getName().equals(currentPool.getName())) {
319	                    prevPool = pool;
320	                    break;
321	                }
322	            }
323	            sb.append("{[")
324	                .append(currentPool.getName())
325	                .append("] [")
326	                .append(prevPool == null ? "?" : prevPool.getUsed())
327	                .append("]->[")
328	                .append(currentPool.getUsed())
329	                .append("]/[")
330	                .append(currentPool.getMax())
331	                .append("]}");
332	        }
333	        return sb.toString();
334	    }
