336	    private static final String OVERHEAD_LOG_MESSAGE = "[gc][{}] overhead, spent [{}] collecting in the last [{}]";
337	
338	    static void logGcOverhead(
339	        final Logger logger,
340	        final JvmMonitor.Threshold threshold,
341	        final long current,
342	        final long elapsed,
343	        final long seq
344	    ) {
345	        switch (threshold) {
346	            case WARN:
347	                if (logger.isWarnEnabled()) {
348	                    logger.warn(OVERHEAD_LOG_MESSAGE, seq, TimeValue.timeValueMillis(current), TimeValue.timeValueMillis(elapsed));
349	                }
350	                break;
351	            case INFO:
352	                if (logger.isInfoEnabled()) {
353	                    logger.info(OVERHEAD_LOG_MESSAGE, seq, TimeValue.timeValueMillis(current), TimeValue.timeValueMillis(elapsed));
354	                }
355	                break;
356	            case DEBUG:
357	                if (logger.isDebugEnabled()) {
358	                    logger.debug(OVERHEAD_LOG_MESSAGE, seq, TimeValue.timeValueMillis(current), TimeValue.timeValueMillis(elapsed));
359	                }
360	                break;
361	        }
362	    }
363	
364	    @Override
365	    protected void doStop() {
366	        if (enabled == false) {
367	            return;
368	        }
369	        scheduledFuture.cancel();
370	    }
