405	                this.elapsed = elapsed;
406	                this.lastJvmStats = lastJvmStats;
407	                this.currentJvmStats = currentJvmStats;
408	                this.maxHeapUsed = maxHeapUsed;
409	            }
410	
411	        }
412	
413	        private long lastTime = now();
414	        private JvmStats lastJvmStats = jvmStats();
415	        private long seq = 0;
416	        private final Map<String, JvmGcMonitorService.GcThreshold> gcThresholds;
417	        final GcOverheadThreshold gcOverheadThreshold;
418	
419	        JvmMonitor(final Map<String, GcThreshold> gcThresholds, final GcOverheadThreshold gcOverheadThreshold) {
420	            this.gcThresholds = Objects.requireNonNull(gcThresholds);
421	            this.gcOverheadThreshold = Objects.requireNonNull(gcOverheadThreshold);
422	        }
